import { jev } from "../../core/client.ts";
import { score } from "../../core/helpers.ts";
import type { ScoreAnswer } from "../../core/types.ts";
import { normalized } from "./normalize.ts";

export const PRIORITY_QUESTIONS = {
  severity: score("How severe is the issue in `ticket`?", [
    "Cosmetic; no impact on functionality",
    "Broken or degraded feature, but a workaround exists",
    "Blocking issue; no workaround exists",
  ]),
  frustration: score("How frustrated is the author of `ticket`?", [
    "Calm, just stating facts",
    "Frustrated but civil",
    "Very angry or threatening to leave",
  ]),
  report_quality: score("How much does `ticket` give an engineer to work with?", [
    "No detail; just says something is broken",
    "Names the feature but no steps or environment",
    "Steps to reproduce or environment, but not both",
    "Steps to reproduce and environment",
  ]),
};

export const PRIORITY_WEIGHTS = { severity: 0.6, frustration: 0.3, report_quality: 0.1 };

export async function ticketPriority(ticket: string): Promise<{ priority: number; parts: Record<string, number> }> {
  const { answers } = await jev.systemOne({ ticket }, PRIORITY_QUESTIONS);
  return combinePriority({
    severity: answers.severity as ScoreAnswer,
    frustration: answers.frustration as ScoreAnswer,
    report_quality: answers.report_quality as ScoreAnswer,
  });
}

export function combinePriority(a: Record<keyof typeof PRIORITY_WEIGHTS, ScoreAnswer>): {
  priority: number;
  parts: Record<string, number>;
} {
  const parts = {
    severity: normalized(a.severity),
    frustration: normalized(a.frustration),
    report_quality: normalized(a.report_quality),
  };
  const priority =
    PRIORITY_WEIGHTS.severity * parts.severity +
    PRIORITY_WEIGHTS.frustration * parts.frustration +
    PRIORITY_WEIGHTS.report_quality * parts.report_quality;
  return { priority: Math.round(priority * 100) / 100, parts };
}

import { jev } from "../../core/client.ts";
import { score } from "../../core/helpers.ts";
import type { ScoreAnswer } from "../../core/types.ts";
import { normalized } from "./normalize.ts";

export const CODE_REVIEW_QUESTIONS = {
  security_risk: score("How much security risk does `diff` carry?", [
    "No surface touched that handles input, auth, or secrets",
    "Handles input or auth, but follows existing safe patterns",
    "Introduces a plausible injection, secret leak, auth bypass, or invalid token handling",
  ]),
  complexity: score("How complex is the change in `diff`?", [
    "Small, local change in one file, obvious on first read",
    "Touches several files, session handling, or adds branching",
    "Cross-cutting change with subtle invariants",
  ]),
  bad_practice: score("Does `diff` follow the conventions in `diff`'s surrounding context?", [
    "Follows existing patterns cleanly",
    "Minor style drift from surrounding code",
    "Works against the established patterns",
  ]),
};

export async function codeReviewRisk(diff: string, commitMessage: string): Promise<{
  risk: number;
  needsHumanReview: boolean;
}> {
  const { answers } = await jev.systemOne({ diff, commit_message: commitMessage }, {
    ...CODE_REVIEW_QUESTIONS,
    commit_quality: score("Does `commit_message` accurately describe `diff`?", [
      "Vague or unrelated to the change",
      "Names the area but misses key parts of the change",
      "Accurately covers the change: names the fix, the session or token work, and the files",
    ]),
  });
  const w = { security_risk: 0.5, complexity: 0.2, bad_practice: 0.1, commit_quality: 0.2 };
  const parts = {
    security_risk: normalized(answers.security_risk as ScoreAnswer),
    complexity: normalized(answers.complexity as ScoreAnswer),
    bad_practice: normalized(answers.bad_practice as ScoreAnswer),
    commit_quality: 1 - normalized(answers.commit_quality as ScoreAnswer), // low quality = high risk
  };
  const risk = Object.entries(w).reduce((acc, [k, weight]) => acc + weight * parts[k as keyof typeof parts], 0);
  return { risk: Math.round(risk * 100) / 100, needsHumanReview: risk >= 0.5 };
}

import { jev } from "../../core/client.ts";
import { score } from "../../core/helpers.ts";
import type { ScoreAnswer } from "../../core/types.ts";
import { normalized } from "./normalize.ts";

export const IDEA_QUESTIONS = {
  problem: score("How real is the problem described in `pitch`?", [
    "Hypothetical; no evidence anyone has this problem",
    "Real problem, but people live with it",
    "Painful, frequent, and people pay to solve it today",
  ]),
  demand: score("How much demand is there for the solution in `pitch`?", [
    "Tiny or unproven audience",
    "Visible niche audience",
    "Large audience actively searching for this",
  ]),
  monetization: score("How credible is the monetization in `pitch`?", [
    "No revenue model or unrealistic one",
    "Plausible model, unproven pricing",
    "Proven buyers or comparable revenue",
  ]),
  differentiation: score("How differentiated is `pitch` from existing alternatives?", [
    "Crowded space, no wedge",
    "A narrow wedge against incumbents",
    "A structural advantage incumbents cannot copy",
  ]),
};

export async function ideaVerdict(pitch: string): Promise<{ verdict: "kill" | "fix" | "ship"; score: number }> {
  const { answers } = await jev.systemOne({ pitch }, IDEA_QUESTIONS);
  const w = { problem: 0.35, demand: 0.25, monetization: 0.2, differentiation: 0.2 };
  const total = (Object.keys(w) as (keyof typeof w)[]).reduce(
    (acc, k) => acc + w[k] * normalized(answers[k] as ScoreAnswer),
    0
  );
  const s = Math.round(total * 100) / 100;
  return { verdict: s >= 0.7 ? "ship" : s >= 0.4 ? "fix" : "kill", score: s };
}
